const CHUNK_SIZE = 1500;
const OVERLAP = 200;
const MAX_CHUNKS = 200;
const MIN_BREAK_OFFSET = Math.floor(CHUNK_SIZE / 2);

const source = $input.first().json;
const webhook = $("Webhook").first().json.body;

if (
  typeof webhook?.executionId !== "string" ||
  typeof webhook?.versionId !== "string"
) {
  throw new Error("Identifiants d’ingestion manquants.");
}

// Ne jamais inventer des pages à partir du texte global.
if (!Array.isArray(source.pages) || source.pages.length === 0) {
  throw new Error(
    "Extraction page par page requise : le champ pages est absent ou vide.",
  );
}

function normalizeText(value) {
  return value
    .normalize("NFC")
    .replace(/\r\n?/g, "\n")
    .replace(/\u00A0/g, " ")
    .replace(/\u0000/g, "")
    .replace(/[ \t]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function findChunkEnd(text, start) {
  const maxEnd = Math.min(start + CHUNK_SIZE, text.length);

  if (maxEnd === text.length) {
    return maxEnd;
  }

  const window = text.slice(start, maxEnd);

  for (const separator of ["\n\n", "\n", " "]) {
    const index = window.lastIndexOf(separator);

    if (index >= MIN_BREAK_OFFSET) {
      return start + index + separator.length;
    }
  }

  return maxEnd;
}

// Valider les pages avant de commencer le découpage.
const seenPages = new Set();

const pages = source.pages.map((entry) => {
  if (
    !Number.isInteger(entry?.page) ||
    entry.page < 1 ||
    typeof entry.text !== "string" ||
    seenPages.has(entry.page)
  ) {
    throw new Error("Page invalide ou numéro de page dupliqué.");
  }

  seenPages.add(entry.page);

  return {
    page: entry.page,
    text: normalizeText(entry.text),
  };
});

pages.sort((a, b) => a.page - b.page);

const chunks = [];

for (const { page, text } of pages) {
  // Ne pas créer de chunk pour une page sans texte.
  // Ne pas renuméroter les pages suivantes.
  if (!text) {
    continue;
  }

  let start = 0;
  let passageDansPage = 0;

  while (start < text.length) {
    const end = findChunkEnd(text, start);

    let contentStart = start;
    let contentEnd = end;

    while (
      contentStart < contentEnd &&
      /\s/.test(text[contentStart])
    ) {
      contentStart++;
    }

    while (
      contentEnd > contentStart &&
      /\s/.test(text[contentEnd - 1])
    ) {
      contentEnd--;
    }

    if (contentEnd > contentStart) {
      passageDansPage++;

      chunks.push({
        position: chunks.length + 1,
        contenu: text.slice(contentStart, contentEnd),
        pageDebut: page,
        pageFin: page,
        reperePassage: `Page ${page} · Passage ${passageDansPage}`,

        // Offsets dans le texte NORMALISÉ de cette page.
        // Ce ne sont pas des coordonnées visuelles du PDF.
        debutCaractere: contentStart,
        finCaractere: contentEnd,
      });

      if (chunks.length > MAX_CHUNKS) {
        throw new Error(
          `Le document dépasse la limite de ${MAX_CHUNKS} chunks.`,
        );
      }
    }

    if (end === text.length) {
      break;
    }

    start = Math.max(start + 1, end - OVERLAP);
  }
}

if (chunks.length === 0) {
  throw new Error("Aucun texte exploitable dans les pages du PDF.");
}

return chunks.map((chunk) => ({
  json: {
    executionId: webhook.executionId,
    versionId: webhook.versionId,
    ...chunk,
    nombreCaracteres: chunk.contenu.length,
    totalChunks: chunks.length,
  },
  pairedItem: {
    item: 0,
  },
}));

