const chunk = $("Nettoyer et decouper").item.json;
const embedding = $json.embedding?.values;

if (
  !Array.isArray(embedding) ||
  embedding.length !== 768 ||
  !embedding.every(
    (value) => typeof value === "number" && Number.isFinite(value)
  )
) {
  throw new Error("Embedding invalide : 768 nombres attendus.");
}

return {
  json: {
    ...chunk,
    embedding,
    modeleEmbedding: "gemini-embedding-2",
  },
};

const items = $input.all().map((item) => item.json);

if (items.length === 0 || items.length > 200) {
  throw new Error("Entre 1 et 200 chunks sont attendus.");
}

const first = items[0];

if (
  typeof first.executionId !== "string" ||
  typeof first.versionId !== "string" ||
  first.modeleEmbedding !== "gemini-embedding-2"
) {
  throw new Error("Identifiants ou modèle d’ingestion invalides.");
}

if (
  !Number.isInteger(first.totalChunks) ||
  first.totalChunks !== items.length
) {
  throw new Error("Le nombre de chunks reçus est incomplet.");
}

for (const item of items) {
  if (
    item.executionId !== first.executionId ||
    item.versionId !== first.versionId ||
    item.modeleEmbedding !== first.modeleEmbedding ||
    item.totalChunks !== first.totalChunks
  ) {
    throw new Error(
      "Les chunks ne correspondent pas à la même ingestion.",
    );
  }
}

items.sort((a, b) => a.position - b.position);

items.forEach((item, index) => {
  if (item.position !== index + 1) {
    throw new Error("Positions manquantes ou dupliquées.");
  }

  if (
    typeof item.contenu !== "string" ||
    item.contenu.trim().length === 0 ||
    item.contenu.length > 1500
  ) {
    throw new Error(
      `Contenu invalide au passage ${item.position}.`,
    );
  }

  // Chaque chunk reste dans une seule page.
  if (
    !Number.isInteger(item.pageDebut) ||
    item.pageDebut < 1 ||
    !Number.isInteger(item.pageFin) ||
    item.pageFin !== item.pageDebut
  ) {
    throw new Error(
      `Pages invalides au passage ${item.position}.`,
    );
  }

  if (
    index > 0 &&
    item.pageDebut < items[index - 1].pageDebut
  ) {
    throw new Error("L’ordre des pages est incohérent.");
  }

  if (
    typeof item.reperePassage !== "string" ||
    item.reperePassage.trim().length === 0 ||
    item.reperePassage.length > 200
  ) {
    throw new Error(
      `Repère invalide au passage ${item.position}.`,
    );
  }

  if (
    !Array.isArray(item.embedding) ||
    item.embedding.length !== 768 ||
    !item.embedding.every(
      (value) =>
        typeof value === "number" &&
        Number.isFinite(value) &&
        Math.abs(value) <= 1_000_000,
    ) ||
    Math.hypot(...item.embedding) < 1e-12
  ) {
    throw new Error(
      `Embedding invalide au passage ${item.position}.`,
    );
  }
});

return [
  {
    json: {
      executionId: first.executionId,
      versionId: first.versionId,
      modeleEmbedding: first.modeleEmbedding,
      totalChunks: items.length,
      chunks: items.map((item) => ({
        position: item.position,
        contenu: item.contenu,
        embedding: item.embedding,
        pageDebut: item.pageDebut,
        pageFin: item.pageFin,
        reperePassage: item.reperePassage,
      })),
    },
  },
];

const source = $json;

if (
  !Array.isArray(source.text) ||
  !source.text.every((text) => typeof text === "string")
) {
  throw new Error(
    "Extraction invalide : désactive Join Pages dans Extract from File.",
  );
}

if (
  !Number.isInteger(source.numpages) ||
  source.numpages < 1 ||
  source.text.length !== source.numpages
) {
  throw new Error(
    "Extraction incomplète : le nombre de textes ne correspond pas aux pages du PDF.",
  );
}

// Conserver les pages vides pour préserver les vrais numéros.
const pages = source.text.map((text, index) => ({
  page: index + 1,
  text,
}));

return {
  json: {
    pages,
    nombrePages: source.numpages,
    hasText: pages.some(
      ({ text }) => text
        .replace(/[\s\u0000\u200B\uFEFF]/g, "")
        .length > 0,
    ),
  },
};
